const row = $input.all()[0].json;
const today = new Date().toLocaleDateString('pl-PL');
const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"/><style>
body{font-family:Arial,sans-serif;background:#f5f5f5;padding:20px;color:#111}
.card{background:#fff;border-radius:8px;padding:20px;margin:10px 0;box-shadow:0 1px 3px rgba(0,0,0,.1)}
h1{color:#b45309;margin:0 0 4px}h2{color:#374151;font-size:13px;text-transform:uppercase;margin-bottom:12px}
.stat{display:inline-block;margin:0 16px 0 0}.num{font-size:28px;font-weight:bold}
.label{font-size:12px;color:#6b7280}.hot{color:#dc2626}
</style></head>
<body>
<div class="card"><h1>AEJaCA — Tygodniowy Digest</h1><p style="color:#6b7280;margin:0">Raport za ostatnie 7 dni &middot; ${today}</p></div>
<div class="card"><h2>Leady</h2>
  <div class="stat"><div class="num">${row.leads_week}</div><div class="label">nowych w tygodniu</div></div>
  <div class="stat"><div class="num">${row.leads_total}</div><div class="label">wszystkich lacznie</div></div>
</div>
<div class="card"><h2>Subskrybenci</h2>
  <div class="stat"><div class="num">${row.subs_week}</div><div class="label">nowych w tygodniu</div></div>
  <div class="stat"><div class="num">${row.subs_total}</div><div class="label">aktywnych lacznie</div></div>
</div>
<div class="card"><h2>Rozmowy (Chat)</h2>
  <div class="stat"><div class="num">${row.convs_week}</div><div class="label">rozmow w tygodniu</div></div>
  <div class="stat"><div class="num ${parseInt(row.hot_leads_week) > 0 ? 'hot' : ''}">${row.hot_leads_week}</div><div class="label">hot leadow</div></div>
</div>
<div class="card"><h2>Analityka</h2>
  <div class="stat"><div class="num">${row.visitors_week}</div><div class="label">unikalnych wizyt</div></div>
  <div class="stat"><div class="num">${row.pageviews_week}</div><div class="label">odslon stron</div></div>
  <div class="stat"><div class="num">${row.inquiries_week}</div><div class="label">zapytan kalk.</div></div>
  ${row.top_page ? '<p style="margin:12px 0 0;color:#6b7280;font-size:13px">Top strona: <strong>' + row.top_page + '</strong></p>' : ''}
</div>
</body></html>`;
return [{ json: { html, subject: 'AEJaCA Digest — ' + today } }];
